SELECT COUNT(*) AS num_orders, SUM(amount) AS total_amount
FROM "order"
WHERE k_symbol = 'POJISTNE';

SELECT COUNT(*) AS clients_born_1970s
FROM client
WHERE birth_date >= '1970-01-01' AND birth_date <= '1979-12-31';

SELECT COUNT(DISTINCT account_id) AS accounts_with_disponent
FROM disp
WHERE type = 'DISPONENT';

SELECT ROUND(AVG(amount)::numeric, 2) AS avg_loan_amount
FROM loan
WHERE EXTRACT(YEAR FROM date) = 1998;
